using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading.Tasks;using System.Diagnostics;using System.Reflection;using System.Security.Cryptography;using Eleon.Modding;using QuantumHangarQc;
class WebGiftTests {
 const string A="76561198000000001",B="76561198000000002",C="76561198000000003";
 static int count;static string area;static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static void Reject(Action a,string expected){try{a();throw new Exception("Expected "+expected);}catch(InvalidDataException e){Check(e.Message.Contains(expected),e.Message+" != "+expected);}}
 static void Run(string name,Action<ArchiveStore,GiftEngine,string> test,int capacity=2){string root=Path.Combine(area,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var s=new ArchiveStore(Path.Combine(root,"Archives"),capacity);var e=new GiftEngine(s,Path.Combine(root,"QuantumWebGift","journal"));test(s,e,root);count++;Console.WriteLine("PASS "+name);}
 static Entry Stored(ArchiveStore s,string owner,int id=200){var e=s.Reserve(new GlobalStructureInfo{id=id,type=4,name="Fixture",factionGroup=1,factionId=50,dockedShips=new List<int>()},owner);string dir=s.DirectoryFor(e);Directory.CreateDirectory(Path.Combine(dir,"Shared"));File.WriteAllText(Path.Combine(dir,"Export.dat"),"fixture export "+id);File.WriteAllText(Path.Combine(dir,"Shared","backup.epb"),"fixture cargo bytes "+id);e.Files=new[]{"Export.dat",Path.Combine("Shared","backup.epb")}.Select(p=>new FileDigest{Path=p,Bytes=new FileInfo(Path.Combine(dir,p)).Length,Sha256=Disk.Hash(Path.Combine(dir,p))}).ToList();e.Status="STORED";e.StoreStage="REMOVING";s.Save(e);return e;}
 static GiftIntent Intent(ArchiveStore s,Entry entry,string recipient=B){return new GiftIntent{Id=Guid.NewGuid().ToString("N"),RequestHash=new string('d',64),Donor=entry.SteamId,Recipient=recipient,ArchiveId=entry.ArchiveId,ManifestHash=Disk.Hash(Path.Combine(s.DirectoryFor(entry),"Manifest.xml")),Expires=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()+120000};}
 static void Crash(string root,string stage){var s=new ArchiveStore(Path.Combine(root,"Archives"),2);var e=new GiftEngine(s,Path.Combine(root,"QuantumWebGift","journal"));e.Fault=x=>{if(x==stage)Environment.Exit(91);};e.Apply(Disk.Read<GiftIntent>(Path.Combine(root,"intent.xml")));throw new Exception("Crash point missing");}
 static void ExitAt(string root,string stage){var p=Process.Start(new ProcessStartInfo{FileName=Environment.GetEnvironmentVariable("QH_TEST_DOTNET")??"dotnet",Arguments="\""+Assembly.GetExecutingAssembly().Location+"\" --crash \""+root+"\" "+stage,UseShellExecute=false});Check(p.WaitForExit(10000),"Child timeout");Check(p.ExitCode==91,"Child exit "+p.ExitCode);}
 static string Sign(string raw,string secret){using(var h=new HMACSHA256(Encoding.UTF8.GetBytes(secret)))return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(raw))).Replace("-","").ToLowerInvariant();}
 static string Queue(string root,GiftIntent i,string secret,string install,string signature=null){string raw=string.Join("\n",new[]{GiftMailbox.Contract,"TEST",install,"GIFT",i.Id,i.Donor,i.Recipient,i.ArchiveId,i.ManifestHash,i.Expires.ToString(System.Globalization.CultureInfo.InvariantCulture)});string p=Path.Combine(root,"QuantumWebGift","requests",i.Id+".xml");Disk.Write(p,new GiftEnvelope{Payload=Convert.ToBase64String(Encoding.UTF8.GetBytes(raw)),Signature=signature??Sign(raw,secret)});return raw;}
 static string[] Receipt(string root,string id){var r=Disk.Read<GiftEnvelope>(Path.Combine(root,"QuantumWebGift","responses",id+".xml"));return Encoding.UTF8.GetString(Convert.FromBase64String(r.Payload)).Split('\n');}
 static GiftMailbox Mailbox(string root,ArchiveStore s,string mode="TEST"){Disk.Write(Path.Combine(root,"QuantumWebGift.xml"),new QuantumWebGiftSettings{Enabled=true,Mode=mode,BoundModPath=root,Secret=new string('a',64),InstallationId=new string('b',32)});return new GiftMailbox(root,s,(a,b)=>true,(a,b)=>{},x=>{});}
 static void Main(string[] args){
 if(args.Length>1&&args[0]=="--seed"){var s=new ArchiveStore(Path.Combine(args[1],"Archives"),2);Stored(s,A);return;}
 if(args.Length>1&&args[0]=="--pump"){var s=new ArchiveStore(Path.Combine(args[1],"Archives"),2);new GiftMailbox(args[1],s,(a,b)=>true,(a,b)=>{},Console.WriteLine).Pump();return;}
if(args.Length>0&&args[0]=="--crash"){Crash(args[1],args[2]);return;}area=args.Length>0?args[0]:Path.Combine(Path.GetTempPath(),"qh-web-gift-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(area);
 Run("gift preserves archive identity and file bytes",(s,e,r)=>{var entry=Stored(s,A);string old=s.DirectoryFor(entry);var i=Intent(s,entry);var result=e.Apply(i);Check(result.State=="COMMITTED","state");Check(!Directory.Exists(old),"old owner absent");var received=s.List(B).Single();Check(received.ArchiveId==entry.ArchiveId&&received.ShipId==entry.ShipId,"identity");s.Verify(received);Check(File.ReadAllText(Path.Combine(s.DirectoryFor(received),"Shared","backup.epb"))=="fixture cargo bytes 200","cargo bytes");Check(s.List(A).Count==0,"donor empty");Check(GiftEngine.Parse<Entry>(result.Before).SteamId==A,"provenance");s.Forget(received);Check(e.Apply(i).State=="COMMITTED","retry after use");Check(s.List(B).Count==0,"no recreated archive");});
 Run("recipient full refuses without modifying donor",(s,e,r)=>{var entry=Stored(s,A);Stored(s,B,201);var i=Intent(s,entry);Reject(()=>e.Apply(i),"RECIPIENT_FULL");Check(s.List(A).Count==1&&s.List(B).Count==1,"quota");},1);
 Run("owner and snapshot guards",(s,e,r)=>{var entry=Stored(s,A);var i=Intent(s,entry);i.Donor=C;Reject(()=>e.Apply(i),"NOT_OWNER");i.Donor=A;i.ManifestHash=new string('0',64);Reject(()=>e.Apply(i),"MANIFEST_CHANGED");i.ManifestHash=Disk.Hash(Path.Combine(s.DirectoryFor(entry),"Manifest.xml"));i.Recipient=A;Reject(()=>e.Apply(i),"REQUEST_INVALID");i.Recipient=B;i.Expires=0;Reject(()=>e.Apply(i),"REQUEST_EXPIRED");});
 Run("quarantine cannot be gifted",(s,e,r)=>{var entry=Stored(s,A);entry.Status="QUARANTINE";s.Save(entry);Reject(()=>e.Apply(Intent(s,entry)),"ARCHIVE_NOT_STORED");});
 Run("corrupt archive refuses without moving",(s,e,r)=>{var entry=Stored(s,A);File.WriteAllText(Path.Combine(s.DirectoryFor(entry),"Export.dat"),"changed");try{e.Apply(Intent(s,entry));throw new Exception("corrupt accepted");}catch(InvalidDataException){Check(s.List(A).Count==1&&s.List(B).Count==0,"preserved");}});
 Run("last slot race has one winner",(s,e,r)=>{var a=Intent(s,Stored(s,A));var c=Intent(s,Stored(s,C,201));var results=new List<string>();Action<GiftIntent> gift=i=>{try{e.Apply(i);lock(results)results.Add("COMMITTED");}catch(InvalidDataException x){lock(results)results.Add(x.Message);}};Task.WaitAll(Task.Run(()=>gift(a)),Task.Run(()=>gift(c)));Check(results.Count(x=>x=="COMMITTED")==1&&results.Count(x=>x=="RECIPIENT_FULL")==1,"one winner");Check(s.List(B).Count==1&&s.List(A).Count+s.List(C).Count==1,"one owner each");},1);
 foreach(var stage in new[]{"PREPARED","MOVED","MANIFEST_WRITTEN","COMMITTED"})Run("process crash recovery "+stage,(s,e,r)=>{var i=Intent(s,Stored(s,A));Disk.Write(Path.Combine(r,"intent.xml"),i);ExitAt(r,stage);var restarted=new GiftEngine(s,Path.Combine(r,"QuantumWebGift","journal"));restarted.RecoverAll();var result=restarted.Apply(i);Check(result.State==(stage=="PREPARED"?"REJECTED":"COMMITTED"),"recovery outcome");Check(s.List(A).Count+s.List(B).Count==1,"one physical archive");Check(s.List(stage=="PREPARED"?A:B).Count==1,"owner");});
 Run("external edit during recovery blocks instead of guessing",(s,e,r)=>{var i=Intent(s,Stored(s,A));Disk.Write(Path.Combine(r,"intent.xml"),i);ExitAt(r,"MOVED");File.WriteAllText(Path.Combine(s.Root,"Players",B,i.ArchiveId,"Export.dat"),"external");Reject(()=>e.RecoverAll(),"ARCHIVE_CHANGED");Check(e.Blocked,"blocked");Check(File.ReadAllText(Path.Combine(s.Root,"Players",B,i.ArchiveId,"Export.dat"))=="external","external preserved");});
 Run("signed mailbox and response idempotency",(s,e,r)=>{var m=Mailbox(r,s);var i=Intent(s,Stored(s,A));var raw=Queue(r,i,new string('a',64),new string('b',32));m.Pump();var receipt=Receipt(r,i.Id);Check(receipt[6]=="COMMITTED"&&receipt[5]==GiftEngine.Hash(Encoding.UTF8.GetBytes(raw)),"signed receipt");Queue(r,i,new string('a',64),new string('b',32));m.Pump();Check(s.List(B).Count==1,"retry no duplicate");i.Recipient=C;Queue(r,i,new string('a',64),new string('b',32));m.Pump();Check(Receipt(r,i.Id)[6]=="COMMITTED"&&s.List(C).Count==0,"reused id does not replace proof");});
 Run("rejected request cannot later become committed",(s,e,r)=>{var m=Mailbox(r,s);var target=Stored(s,B,201);var i=Intent(s,Stored(s,A));Queue(r,i,new string('a',64),new string('b',32));m.Pump();Check(Receipt(r,i.Id)[6]=="REJECTED","full rejected");s.Forget(target);Queue(r,i,new string('a',64),new string('b',32));m.Pump();Check(Receipt(r,i.Id)[6]=="REJECTED"&&s.List(B).Count==0&&s.List(A).Count==1,"no delayed gift");},1);
 Run("simulation pairing and forged signatures cannot transfer",(s,e,r)=>{Reject(()=>Mailbox(r,s,"SIMULATION"),"PAIRING_INVALID");var m=Mailbox(r,s);var i=Intent(s,Stored(s,A));Queue(r,i,new string('a',64),new string('b',32),new string('0',64));m.Pump();Check(s.List(A).Count==1&&s.List(B).Count==0,"forgery blocked");Check(!File.Exists(Path.Combine(r,"QuantumWebGift","responses",i.Id+".xml")),"no false receipt");});
 Console.WriteLine("PASS "+count+" native gift tests; archive bytes are fixtures, real game cargo NOT_TESTED.");
 }
}
